def semver_sort(versions):
    def make_key(v):
        # strip build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
            has_pre = 0
        else:
            core = main
            pre = None
            has_pre = 1

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is not None:
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident), ''))
                else:
                    pre_key.append((1, 0, ident))
            pre_key = tuple(pre_key)
        else:
            pre_key = ()

        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=make_key)

